//! Example: Layout optimization with a wind resource grid (WRG)
//!
//! This example compares a layout optimization using a WindRoseWRG. In the
//! example, two turbine positions are optimized within a square grid. The
//! optimization is run 3 times:
//!
//! 1. Using a WindRoseWRG object generated using the example wrg file
//! 2. Using a WindRose object created from the WindRoseWRG object
//! 3. Using a WindRose object created from the WindRoseWRG object, but with
//!    the HeterogeneousMap also generated by the WindRoseWRG object
//!
//! Because the WRG file includes a speed-up for the northern winds, the
//! optimizations (1) and (3) place both turbines near the northern boundary
//! of the grid, while the optimization (2) places the turbines in the
//! furthest corners of the grid.
//!
//! Scenario aligned 1:1 with
//! examples_wind_resource_grid/003_wrg_compar_layout_optimization.py.
//!
//! Note: Python runs the search until a wall-clock deadline (30 s per
//! individual and 120 s in total), so its result is not reproducible; the
//! Rust example runs a fixed number of generations and iterations instead.

use florus::floris_model::FlorisModel;
use florus::optimization::layout_optimization::layout_optimization_base::{
    Boundary, LayoutOptimizationConfig,
};
use florus::optimization::layout_optimization::{LayoutOptimizationRandomSearch, LayoutOptimizer};
use florus::types::Array1;
use florus::wind_data::{WindData, WindRoseWRG};

/// The number of turbine diameters between the turbines
const MIN_DIST_D: f64 = 3.0;

/// Run the layout optimization for the given wind data and return the
/// optimized layout and its AEP.
fn optimize(
    fmodel: &FlorisModel,
    boundaries: &Boundary,
    layout_x: &Array1,
    layout_y: &Array1,
    label: &str,
) -> anyhow::Result<(Array1, Array1, f64)> {
    let mut fmodel = fmodel.clone();
    fmodel.set_layout(layout_x, layout_y)?;
    fmodel.run()?;

    // The AEP of the initial layout (Python's `describe`)
    let initial_aep = fmodel.get_expected_farm_power(None, None)? * 8760.0 / 1e9;
    println!("=====================================");
    println!("{label}");
    println!("  Initial AEP = {initial_aep:.3} [GWh]");

    let config = LayoutOptimizationConfig {
        boundaries: boundaries.clone(),
        min_dist: Some(MIN_DIST_D * 126.0),
        // Python runs the search until a wall-clock deadline (30 s per
        // individual); the Rust example runs a fixed number of iterations
        max_iterations: 100,
        n_generations: 2,
        use_dist_based_init: false,
        ..Default::default()
    };
    let mut optimizer = LayoutOptimizationRandomSearch::new(&fmodel, boundaries.clone(), 4)?
        .with_config(config)
        .with_random_seed(1);
    let solution = optimizer.optimize()?;

    println!("  x = {:?}", solution.x);
    println!("  y = {:?}", solution.y);
    println!("  Final AEP = {:.3} [GWh]", solution.value / 1e9);
    println!(
        "  ({:+.2} %)",
        100.0 * (solution.value / 1e9 - initial_aep) / initial_aep
    );

    Ok((solution.x, solution.y, solution.value))
}

fn main() -> anyhow::Result<()> {
    // Initialize the WindRoseWRG object with wind speeds every 1 m/s and a
    // fixed ti of 6%. Specify a wd_step of 2 degrees, which implies
    // upsampling from wrg's 90 degree sectors to 2 degree sectors.
    let mut wind_rose_wrg = WindRoseWRG::new(
        "examples/inputs/wrg_example.wrg",
        Some(2.0),
        Some(Array1::from_iter((0..21).map(|i| i as f64))),
        None,
    )?;
    wind_rose_wrg.set_ti_table(0.06);

    // Define an optimization boundary within the grid that is a square with a
    // buffer to avoid the outer limits of the heterogeneous area
    let buffer = 100.0;
    let boundaries = Boundary::Polygon(vec![
        (buffer, buffer),
        (1000.0 - buffer, buffer),
        (1000.0 - buffer, 2000.0 - buffer),
        (buffer, 2000.0 - buffer),
        (buffer, buffer),
    ]);

    // Select an initial layout in the corners of the boundary
    let layout_x = Array1::from_vec(vec![500.0, 1000.0 - buffer]);
    let layout_y = Array1::from_vec(vec![900.0, 2000.0 - buffer]);

    // Set up the FlorisModel
    let fmodel = FlorisModel::from_file("examples/inputs/gch.yaml")?;

    // Use the heterogeneous wind rose to represent the information in the
    // WindRoseWRG as a single WindRose object (for one location) and a
    // HeterogeneousMap that describes the speed ups per direction across
    // the domain.
    let wind_rose_het =
        wind_rose_wrg.get_heterogeneous_wind_rose(&fmodel, None, Some(0.0), Some(0.0), 9.0)?;

    // Run the optimization with the full WindRoseWRG first
    let mut wind_rose_wrg_layout = wind_rose_wrg.clone();
    wind_rose_wrg_layout.set_layout(layout_x.clone(), layout_y.clone())?;
    let mut fmodel_wrg = fmodel.clone();
    fmodel_wrg.set_wind_data(&wind_rose_wrg_layout)?;
    let (x_wrg, y_wrg, aep_wrg) = optimize(
        &fmodel_wrg,
        &boundaries,
        &layout_x,
        &layout_y,
        "Optimized layout (WRG)",
    )?;

    // Repeat using the wind rose with the heterogeneous map
    let mut fmodel_het = fmodel.clone();
    fmodel_het.set_wind_data(&wind_rose_het)?;
    let (x_het, y_het, aep_het) = optimize(
        &fmodel_het,
        &boundaries,
        &layout_x,
        &layout_y,
        "Optimized layout (single wind rose + het)",
    )?;

    // Repeat using the single wind rose (without the heterogeneous map)
    let wind_rose = wind_rose_wrg.get_wind_rose_at_point(0.0, 0.0, None, None, None);
    let mut fmodel_wr = fmodel.clone();
    fmodel_wr.set_wind_data(&wind_rose)?;
    let (x_wr, y_wr, aep_wr) = optimize(
        &fmodel_wr,
        &boundaries,
        &layout_x,
        &layout_y,
        "Optimized layout (single wind rose)",
    )?;

    // The AEP of the initial layout
    let mut fmodel_initial = fmodel.clone();
    fmodel_initial.set_layout(&layout_x, &layout_y)?;
    fmodel_initial.set_wind_data(&wind_rose_wrg_layout)?;
    fmodel_initial.run()?;
    let aep_initial = fmodel_initial.get_expected_farm_power(None, None)? * 8760.0 / 1e9;
    println!("=====================================");
    println!("Initial layout: AEP = {aep_initial:.3} [GWh]");
    println!("  x = {:?}", layout_x);
    println!("  y = {:?}", layout_y);

    // The optimized layouts
    println!("=====================================");
    println!("x_wrg = {x_wrg:?}, y_wrg = {y_wrg:?}");
    println!("x_wr = {x_wr:?}, y_wr = {y_wr:?}");
    println!("x_het = {x_het:?}, y_het = {y_het:?}");
    println!(
        "Final AEPs: WRG {:.3} GWh, single wind rose {:.3} GWh, het {:.3} GWh",
        aep_wrg / 1e9,
        aep_wr / 1e9,
        aep_het / 1e9
    );

    Ok(())
}
